const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function download(name,text,type='application/json'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500)}
function tabs(){ $$('.tab').forEach(b=>b.addEventListener('click',()=>{$$('.tab').forEach(x=>x.setAttribute('aria-selected','false'));$$('.panel').forEach(x=>x.classList.remove('active'));b.setAttribute('aria-selected','true');$('#'+b.dataset.tab).classList.add('active')}));}
function chips(values,extra=''){return (values||[]).map(v=>`<span class="chip ${extra}">${esc(v)}</span>`).join('')}
function subtypeBlock(r){
  if(r.bloodlines?.length)return `<h4 style="color:var(--gold)">Canonical bloodlines</h4>${r.bloodlines.map(b=>`<div class="blood"><strong>${esc(b.name)}</strong><br><span class="meta">${esc(b.description)}</span></div>`).join('')}`;
  if(r.forms?.length)return `<h4 style="color:var(--gold)">Canonical forms — not bloodlines</h4>${r.forms.map(b=>`<div class="blood"><strong>${esc(b.name)}</strong><br><span class="meta">${esc(b.description)}</span></div>`).join('')}`;
  return `<p class="subtype-empty">No formal bloodlines are assigned to this race.</p>`;
}
function absorbedBlock(r){
  if(!r.absorbedRaces?.length)return '';
  return `<div class="merge-list">${r.absorbedRaces.map(m=>`<div class="merge-row"><b>${esc(m.name)}</b> (${m.similarity}% · ${esc(m.formerRegistry)})<br><span class="meta">${esc(m.rationale)}</span></div>`).join('')}</div>`;
}
function deityBlock(r){
  if(!r.deityAssignments?.length)return '';
  return `<section class="deity-panel"><h4>Associated deities</h4>${r.deityAssignments.map(d=>`<div class="deity-row"><div><b>${esc(d.name)}</b> <span class="deity-role">${esc(d.role)}</span></div><div class="deity-title">${esc((d.titles||[])[0]||'Universal deity')} · ${esc((d.domains||[]).slice(0,4).join(' · '))}</div><div>${esc(d.rationale)}</div></div>`).join('')}<p class="deity-note">${esc(r.deityAssignmentNote)}</p></section>`
}
function raceCard(r){return `<article class="card"><div class="score">${r.absorbedRaces?.length?'80%+ merged':'distinct'}</div><div class="kicker">${esc(r.category)}</div><h3>${esc(r.name)}</h3><div class="meta">${esc(r.worldClass)}</div><div class="chips">${chips([r.origin==='compensation'?'Compensation race':r.origin==='replacement'?'Consolidated replacement':'Project-original core'],r.origin==='compensation'?'comp':'')}${chips(r.biomes,'biome')}</div><p>${esc(r.summary)}</p>${deityBlock(r)}<div class="facts"><div class="fact"><b>Body</b>${esc(r.body)}</div><div class="fact"><b>Society</b>${esc(r.society)}</div><div class="fact"><b>Abilities</b>${esc(r.abilities.join(' · '))}</div><div class="fact"><b>Limits</b>${esc(r.limits.join(' · '))}</div></div><div class="biome-note">${esc(r.biomeBasis)}</div><details class="details"><summary>Subtypes, deity associations, merge audit, naming blend, and design notes</summary>${subtypeBlock(r)}${absorbedBlock(r)}<p class="policy"><b>Subtype policy:</b> ${esc(r.bloodlinePolicy)}</p><p><b>Generator blend:</b> ${esc(Object.entries(r.blend||{}).map(([k,v])=>v+'% '+(window.MythBlend?.cultureById(k)?.label||k)).join(' · '))}</p><p><b>Name collision check:</b> ${esc(r.nameCheck||'Pre-existing project-original name')}. This is not proof against unindexed or future use.</p><p><b>Design note:</b> ${esc(r.designNotes||'Project-original record retained and rewritten system-neutrally.')}</p></details></article>`}
function renderRaces(){const q=$('#raceSearch').value.toLowerCase().trim(), cat=$('#raceCat').value, origin=$('#raceOrigin').value, biome=$('#raceBiome').value, deity=$('#raceDeity').value;let rows=APP.races.filter(r=>(!q||JSON.stringify(r).toLowerCase().includes(q))&&(!cat||r.category===cat)&&(!origin||r.origin===origin)&&(!biome||r.biomes.includes(biome))&&(!deity||r.deityAssignments?.some(d=>d.name===deity)));$('#raceCount').textContent=`${rows.length} of ${APP.races.length} greenhouse-homeworld fantasy peoples`;$('#raceGrid').innerHTML=rows.map(raceCard).join('')||'<div class="empty">No peoples match these filters.</div>'}
function biomeOptions(){return Object.entries(APP.biomeCatalog).flatMap(([cat,subs])=>subs.map(s=>`${cat} / ${s}`))}
function initRaceFilters(){const cats=[...new Set(APP.races.map(r=>r.category))].sort();$('#raceCat').innerHTML='<option value="">All categories</option>'+cats.map(x=>`<option>${esc(x)}</option>`).join('');$('#raceBiome').innerHTML='<option value="">All biomes</option>'+biomeOptions().map(x=>`<option>${esc(x)}</option>`).join('');$('#raceDeity').innerHTML='<option value="">All deities</option>'+APP.pantheon.map(d=>`<option>${esc(d.name)}</option>`).join('');['input','change'].forEach(ev=>['#raceSearch','#raceCat','#raceOrigin','#raceBiome','#raceDeity'].forEach(s=>$(s).addEventListener(ev,renderRaces)));renderRaces();}
function renderComp(){ $('#compTable tbody').innerHTML=APP.compensation.map(x=>`<tr><td>${String(x.slot).padStart(2,'0')}</td><td>${esc(x.recordRange)}</td><td>${esc(x.sourceCategories.join(' + '))}</td><td><b>${esc(x.replacementRace)}</b></td><td>${esc(x.policy)}</td><td>${esc(x.currentDisposition)}</td></tr>`).join('') }
function alienCard(a){return `<article class="card"><div class="score">distinct</div><div class="kicker">Alien-Folk · unified comparison complete</div><h3>${esc(a.name)}</h3><div class="chips">${chips(a.biomes,'biome')}</div><p>${esc(a.summary)}</p><div class="biome-note">${esc(a.biomeBasis)}</div><details class="details"><summary>Comparison and subtype policy</summary><p>${esc(a.status)}</p><p class="policy"><b>Subtype policy:</b> ${esc(a.bloodlinePolicy)}</p></details></article>`}
function renderAliens(){const q=$('#alienSearch').value.toLowerCase().trim(), biome=$('#alienBiome').value;const rows=APP.aliens.filter(a=>(!q||JSON.stringify(a).toLowerCase().includes(q))&&(!biome||a.biomes.includes(biome)));$('#alienCount').textContent=`${rows.length} of ${APP.aliens.length} surviving alien peoples`;$('#alienGrid').innerHTML=rows.map(alienCard).join('')||'<div class="empty">No alien peoples match.</div>'}
function renderLedger(){
  $('#merge80List').innerHTML=`<article class="notice"><b>Mixed-heritage removal:</b> ${esc(APP.removedMixedHeritage.reason)}</article>`+APP.merge80.map(x=>`<article><h3>${esc(x.absorbed)} → ${esc(x.survivor)} <span class="chip">${x.score}%</span></h3><div class="meta">${esc(x.absorbedRegistry)} into ${esc(x.survivorRegistry)} · ${esc(x.precedence)}</div><p>${esc(x.rationale)}</p></article>`).join('');
  $('#ledgerList').innerHTML=APP.ledger.map(x=>`<article><h3>${esc(x.file)}</h3><div>${esc(x.role)}</div></article>`).join('');
}
function stats(){const s=APP.stats;$('#stats').innerHTML=[['Fantasy peoples',s.fantasyFinal],['Alien peoples',s.alienPreserved],['Deity-assigned races',s.deityAssignedRaces],['Pantheon represented',s.deitiesRepresented],['Biomes assigned',s.biomeAssigned],['Canonical bloodline races',s.bloodlineRaces]].map(([a,b])=>`<div class="stat"><strong>${esc(b)}</strong><span>${esc(a)}</span></div>`).join('')}
function selfCheck(){
  const all=[...APP.races,...APP.aliens], names=all.map(r=>r.name.toLocaleLowerCase()), dupe=names.filter((n,i)=>names.indexOf(n)!==i);
  const allowed=new Set(biomeOptions()), forbidden=/^(Desert|Tundra|Arctic|Alien) \//;
  const allowedBloodlines=new Set(['kaluseban','szucarin','panolima','deorbasun','drilthar']);
  const deityNames=new Set(APP.pantheon.map(d=>d.name)), assignedDeities=new Set(APP.races.flatMap(r=>(r.deityAssignments||[]).map(d=>d.name)));
  const tests=[
    ['one embedded application shell',document.querySelectorAll('html').length===1],
    ['34 fantasy peoples after removal and 80% merges',APP.races.length===34],
    ['26 alien peoples after cross-registry merges',APP.aliens.length===26],
    ['60 total surviving races',all.length===60],
    ['18 supported merges meet the 80% floor',APP.merge80.length===18&&APP.merge80.every(x=>x.score>=80)],
    ['every surviving race has 1–5 approved biomes',all.every(r=>r.biomes?.length>=1&&r.biomes.length<=5&&r.biomes.every(b=>allowed.has(b)))],
    ['homeworld races have no desert, ice, arctic, or alien-only biome',APP.races.every(r=>r.biomes.every(b=>!forbidden.test(b)))],
    ['every fantasy race has one or more deity associations',APP.races.every(r=>r.deityAssignments?.length>=1)],
    ['all deity associations use the 22-name pantheon',APP.races.every(r=>r.deityAssignments.every(d=>deityNames.has(d.name)))],
    ['all 22 deities are represented by at least one fantasy race',assignedDeities.size===22&&[...deityNames].every(n=>assignedDeities.has(n))],
    ['alien races have no deity assignments',APP.aliens.every(r=>!Object.hasOwn(r,'deityAssignments'))],
    ['no active race carries a generated community field',all.every(r=>!Object.hasOwn(r,'community'))],
    ['bloodlines exist only on five canon races',APP.races.every(r=>r.bloodlines?.length?allowedBloodlines.has(r.id):true)&&APP.races.filter(r=>r.bloodlines?.length).length===5],
    ['Jaspey uses forms rather than bloodlines',!!APP.races.find(r=>r.id==='jaspey'&&r.forms?.length===3&&!r.bloodlines)],
    ['mixed-heritage Or’El removed',!APP.races.some(r=>r.id==='orel'||/mixed heritage/i.test(r.category))],
    ['no duplicate survivor names',dupe.length===0],
    ['optional bloodline generator loaded',!!window.MythGenerators?.bloodline]
  ];
  $('#checkOutput').innerHTML=tests.map(([n,p])=>`${p?'PASS':'FAIL'}  ${n}`).join('\n');$('#checkOutput').className='selfcheck '+(tests.every(x=>x[1])?'pass':'fail')
}
// Foundry
let rows=[];function cultureOptions(sel=''){return window.MYTHWEAVER_DATA.cultures.map(c=>`<option value="${c.id}" ${c.id===sel?'selected':''}>${esc(c.label)}</option>`).join('')}
function addBlend(id='germanic',weight=34){rows.push({uid:crypto.randomUUID?crypto.randomUUID():Math.random().toString(36).slice(2),id,weight});drawBlend()}
function drawBlend(){const box=$('#blendRows');box.innerHTML=rows.map(r=>`<div class="blend-row" data-uid="${r.uid}"><select class="control blend-culture">${cultureOptions(r.id)}</select><input class="control blend-weight" type="number" min="1" max="100" value="${r.weight}"><button aria-label="Remove">×</button></div>`).join('');box.querySelectorAll('.blend-row').forEach(el=>{const r=rows.find(x=>x.uid===el.dataset.uid);el.querySelector('select').onchange=e=>r.id=e.target.value;el.querySelector('input').oninput=e=>r.weight=Number(e.target.value||0);el.querySelector('button').onclick=()=>{rows=rows.filter(x=>x.uid!==r.uid);drawBlend()}})}
function blendObject(){const out={};rows.forEach(r=>out[r.id]=(out[r.id]||0)+Math.max(0,r.weight));return window.MythBlend.normalizeBlend(out)}
function genFoundry(){const blend=blendObject(), seed=$('#foundrySeed').value||'universal-foundry', count=Math.max(1,Math.min(8,Number($('#foundryCount').value||3))), mode=document.querySelector('input[name=foundryMode]:checked').value;let out=[];for(let i=0;i<count;i++){const rng=new window.MythRandom.SeededRandom(seed+'-'+i);if(mode==='race')out.push(window.MythGenerators.race(blend,rng,{diacritics:$('#foundryDia').checked,intensity:Number($('#foundryIntensity').value)}));else if(mode==='bloodline')out.push(window.MythGenerators.bloodline(blend,rng,{diacritics:$('#foundryDia').checked,intensity:Number($('#foundryIntensity').value)}));else out.push(...window.MythGenerators.pair(blend,rng,{diacritics:$('#foundryDia').checked,intensity:Number($('#foundryIntensity').value)}));}window.lastGenerated=out;$('#foundryResults').innerHTML=out.map(x=>`<article class="generated"><div class="kicker">${esc(x.type)}</div><h3>${esc(x.name)}</h3><div class="meta">${esc(x.pronunciation||'')} · seed ${esc(x.seed||seed)}</div><div class="blendbar">${Object.values(x.blend||blend).map(v=>`<i style="width:${v}%"></i>`).join('')}</div><p>${esc(x.summary)}</p>${x.type==='bloodline'?`<p><b>Bloodline type:</b> ${esc(x.bloodlineType)} · <b>Parent race:</b> ${esc(x.parentRace)}</p><p class="policy">${esc(x.useRule)}</p>`:`<p><b>Plural:</b> ${esc(x.plural)} · <b>Language:</b> ${esc(x.language)}</p><p class="policy">${esc(x.bloodlinePolicy)}</p>`}<details><summary>Full generated dossier</summary><pre class="selfcheck">${esc(JSON.stringify(x,null,2))}</pre></details></article>`).join('')}
function initFoundry(){addBlend('germanic',45);addBlend('japanese',30);addBlend('greek',25);$('#addCulture').onclick=()=>addBlend('celtic',10);$('#generateNames').onclick=genFoundry;$('#exportGenerated').onclick=()=>download('universal_generated_names.json',JSON.stringify(window.lastGenerated||[],null,2));}
document.addEventListener('DOMContentLoaded',()=>{tabs();stats();initRaceFilters();renderComp();renderAliens();renderLedger();initFoundry();$('#alienBiome').innerHTML='<option value="">All biomes</option>'+biomeOptions().map(x=>`<option>${esc(x)}</option>`).join('');$('#alienSearch').addEventListener('input',renderAliens);$('#alienBiome').addEventListener('change',renderAliens);$('#exportRaces').onclick=()=>download('universal_homebrew_races_with_biomes_and_deities.json',JSON.stringify({races:APP.races,aliens:APP.aliens,pantheon:APP.pantheon,deityAssignmentPolicy:APP.deityAssignmentPolicy,merge80:APP.merge80,biomeCatalog:APP.biomeCatalog},null,2));$('#printBtn').onclick=()=>window.print();$('#runChecks').onclick=selfCheck;selfCheck();});
